t = int(input())
for i in range(t):
	(x, y, n, s, e, w, p) = map(int, input().split())
	wa = x * e + y * n
	c = x + y
	p -= wa
	if p < 0:
		print(-1)
	elif p == 0:
		print(x + y)
	else:
		li = [n + s, e + w]
		li.sort(reverse=True)
		j = 0
		while p % li[0] != 0:
			p -= li[1]
			j += 2
			if p == 0:
				print(x + y + j)
			if p < 0:
				print(-1)
				break
		if p > 0:
			j += 2 * p // li[0]
			print(x + y + j)
